<?php
declare(strict_types=1); require_once dirname(__DIR__,2).'/config/database.php'; require_once dirname(__DIR__,2).'/includes/auth.php'; requireAdmin();
$errors=[];$notice='';$edit=null;
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!verifyCsrfToken())$errors[]='Permintaan tidak valid. Silakan coba lagi.';else{$a=(string)($_POST['action']??'');$id=(int)($_POST['lemari_id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT COUNT(*) FROM rak WHERE lemari_id=:id');$s->execute(['id'=>$id]);if((int)$s->fetchColumn())$errors[]='Lemari masih memiliki rak dan tidak dapat dihapus.';else{$pdo->prepare('DELETE FROM lemari WHERE lemari_id=:id')->execute(['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'DELETE');$notice='Lemari berhasil dihapus.';}}if(in_array($a,['create','update'],true)){$v=['ruangan_id'=>(int)($_POST['ruangan_id']??0),'kode_lemari'=>trim((string)($_POST['kode_lemari']??'')),'nama_lemari'=>trim((string)($_POST['nama_lemari']??''))?:null,'keterangan'=>trim((string)($_POST['keterangan']??''))?:null];if(!$v['ruangan_id']||$v['kode_lemari']==='')$errors[]='Ruangan dan kode lemari wajib diisi.';$s=$pdo->prepare('SELECT ruangan_id FROM ruangan WHERE ruangan_id=:id');$s->execute(['id'=>$v['ruangan_id']]);if(!$s->fetch())$errors[]='Ruangan tidak valid.';$s=$pdo->prepare('SELECT lemari_id FROM lemari WHERE ruangan_id=:ruangan_id AND kode_lemari=:kode_lemari AND lemari_id!=:id');$s->execute(['ruangan_id'=>$v['ruangan_id'],'kode_lemari'=>$v['kode_lemari'],'id'=>$id]);if($s->fetch())$errors[]='Kode lemari sudah digunakan pada ruangan ini.';if(!$errors&&$a==='create'){$pdo->prepare('INSERT INTO lemari (ruangan_id,kode_lemari,nama_lemari,keterangan) VALUES (:ruangan_id,:kode_lemari,:nama_lemari,:keterangan)')->execute($v);logActivity($pdo,(int)$_SESSION['user_id'],'CREATE');$notice='Lemari berhasil ditambahkan.';}if(!$errors&&$a==='update'&&$id){$pdo->prepare('UPDATE lemari SET ruangan_id=:ruangan_id,kode_lemari=:kode_lemari,nama_lemari=:nama_lemari,keterangan=:keterangan WHERE lemari_id=:id')->execute($v+['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'UPDATE');$notice='Lemari berhasil diperbarui.';}}}}
if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM lemari WHERE lemari_id=:id');$s->execute(['id'=>(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$rooms=$pdo->query('SELECT r.ruangan_id,r.kode_ruangan,r.nama_ruangan,u.nama_unit FROM ruangan r JOIN unit_kerja u ON u.unit_id=r.unit_id ORDER BY u.nama_unit,r.nama_ruangan')->fetchAll();$q=trim((string)($_GET['q']??''));$s=$pdo->prepare('SELECT l.*,r.nama_ruangan,u.nama_unit,(SELECT COUNT(*) FROM rak x WHERE x.lemari_id=l.lemari_id) rack_count FROM lemari l JOIN ruangan r ON r.ruangan_id=l.ruangan_id JOIN unit_kerja u ON u.unit_id=r.unit_id WHERE l.kode_lemari LIKE :q1 OR COALESCE(l.nama_lemari,\'\') LIKE :q2 ORDER BY u.nama_unit,r.nama_ruangan,l.kode_lemari');$s->execute(['q1'=>"%$q%",'q2'=>"%$q%"]);$items=$s->fetchAll();
