<section class="panel master-form"><h2><?= $edit?'Edit':'Tambah'?> Lemari</h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="lemari_id" value="<?=(int)$edit['lemari_id']?>"><?php endif;?><label>Ruangan<select name="ruangan_id" required><option value="">Pilih ruangan</option><?php foreach($rooms as $r):?><option value="<?=(int)$r['ruangan_id']?>" <?=((int)($edit['ruangan_id']??0)===(int)$r['ruangan_id'])?'selected':''?>><?=e($r['nama_unit'].' - '.$r['kode_ruangan'].' '.$r['nama_ruangan'])?></option><?php endforeach;?></select></label><label>Kode Lemari<input name="kode_lemari" required maxlength="50" value="<?=e($edit['kode_lemari']??'')?>"></label><label>Nama Lemari<input name="nama_lemari" maxlength="100" value="<?=e($edit['nama_lemari']??'')?>"></label><label>Keterangan<textarea name="keterangan" maxlength="255"><?=e($edit['keterangan']??'')?></textarea></label><div><button class="primary-button">Simpan</button></div></form></section><section class="panel user-list"><h2>Daftar Lemari</h2><form class="filter-form"><input name="q" value="<?=e($q)?>" placeholder="Cari kode atau nama"><button>Cari</button></form><div class="table-wrap"><table><thead><tr><th>Unit</th><th>Ruangan</th><th>Kode</th><th>Nama</th><th>Rak</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['nama_unit'])?></td><td><?=e($x['nama_ruangan'])?></td><td><?=e($x['kode_lemari'])?></td><td><?=e($x['nama_lemari']??'-')?></td><td><?=(int)$x['rack_count']?></td><td><a href="lemari.php?edit=<?=(int)$x['lemari_id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="lemari_id" value="<?=(int)$x['lemari_id']?>"><button>Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>